param([Parameter(Mandatory=$true)][string]$RunDirectory,[Parameter(Mandatory=$true)][string]$RomPath,[string]$NaturalRunsDirectory)
$ErrorActionPreference='Stop'
function Hash([string]$p,[string]$alg='SHA256'){$h=[Security.Cryptography.HashAlgorithm]::Create($alg);([BitConverter]::ToString($h.ComputeHash([IO.File]::ReadAllBytes($p)))-replace '-','')}
function Hex([byte[]]$b){([BitConverter]::ToString($b)-replace '-','')}
function HashBytes([byte[]]$b){$h=[Security.Cryptography.SHA256]::Create();([BitConverter]::ToString($h.ComputeHash($b))-replace '-','')}
$target="$PSScriptRoot/../evidence/mpu4/collection";$cases=@((Get-Content "$RunDirectory/cases.json" -Raw|ConvertFrom-Json)|ForEach-Object {$_});if($cases.Count -ne 2){throw 'Unexpected case count'};if((Get-Content "$RunDirectory/exit-code.txt" -Raw).Trim() -ne '0'){throw 'Capture incomplete'};if((Hash $RomPath 'SHA1') -ne '402D1518BB78FDC489B06C2AABC771E5CE151847'){throw 'Unexpected ROM'}
if($cases[0].kind -ne 'empty' -or $cases[1].kind -ne 'queued8784'){throw 'Unexpected fixture kinds'}
$rom=[IO.File]::ReadAllBytes($RomPath)
if($rom[0xFEC9] -ne 0xBD -or $rom[0xFECA] -ne 0x5C -or $rom[0xFECB] -ne 0xD0 -or $rom[0xFECC] -ne 0x0F -or $rom[0xFECD] -ne 0x2C){throw 'FEC9/FECC source contract differs'}
$returnAddress=0xFECC
$states=@{};$rows=[Collections.Generic.List[object]]::new();$active=$null
foreach($line in (Get-Content "$RunDirectory/debug.log")){if($line -notmatch '^W([SIFR]) '){continue};$kind=$Matches[1];$fields=@{};foreach($match in [regex]::Matches($line,'([a-z0-9_]+)=([0-9A-F]+)')){$fields[$match.Groups[1].Value]=[Convert]::ToUInt64($match.Groups[2].Value,16)}
 if($kind -eq 'R'){if($null -ne $active -or [int]$fields.id -ne $cases[$rows.Count].id){throw 'Unexpected initial state'};$states[[int]$fields.id]=[ordered]@{pc=$fields.pc;cycle=$fields.cycle;s=$fields.s;u=$fields.u;x=$fields.x;y=$fields.y;dp=$fields.dp;cc=$fields.cc};continue}
 if($kind -eq 'S'){if($null -ne $active){throw 'Unfinished case'};$id=[int]$fields.id;if($id -ne $cases[$rows.Count].id -or !$states.ContainsKey($id)){throw 'Unexpected case id'};$active=[ordered]@{case=$cases[$rows.Count];initial=$states[$id];start_cycle=$fields.cycle;instructions=[Collections.Generic.List[object]]::new()}}
 if($null -eq $active -or $fields.id -ne $active.case.id){throw 'Mismatched case'}
 if($kind -in @('S','I')){if($line -notmatch 'bytes=([0-9A-F]{10})'){throw 'Missing context'};$hex=$Matches[1];$pc=[int]$fields.pc;for($n=0;$n -lt 5;$n++){if([Convert]::ToByte($hex.Substring($n*2,2),16) -ne $rom[$pc+$n]){throw 'ROM context differs'}};$active.instructions.Add([ordered]@{pc=$pc;cycle=$fields.cycle;context_hex=$hex})}
  else{if($fields.pc -ne 0xFECE -or $fields.s -ne 0x700 -or $fields.w2c -ne 0){throw 'Unexpected wrapper end'};$active['cycles']=$fields.cycle-$active.start_cycle;$active['end']=[ordered]@{pc=$fields.pc;cycle=$fields.cycle;s=$fields.s;w2c=$fields.w2c};$id=$active.case.id;$before=[IO.File]::ReadAllBytes("$RunDirectory/timer1-$id-before.bin");$after=[IO.File]::ReadAllBytes("$RunDirectory/timer1-$id-after.bin");if($before.Length -ne 0x800 -or $after.Length -ne 0x800){throw 'Case RAM is not2KB'};if($active.case.kind -eq 'empty'){if((($before[0x47]*256)+$before[0x48]) -ne 0){throw 'Empty fixture has a queued head'}}else{if((($before[0x47]*256)+$before[0x48]) -ne 0x1A0 -or (($before[0x1A8]*256)+$before[0x1A9]) -ne 0x8784){throw 'Queued8784 fixture task differs'}};if((($after[0x6FE]*256)+$after[0x6FF]) -ne $returnAddress -or $after[0x2C] -ne 0){throw 'Captured frame/return contract differs'};if($active.instructions.Count -lt 2 -or $active.instructions[0].pc -ne 0xFEC9 -or $active.instructions[-1].pc -ne 0xFECC){throw 'Missing wrapper boundaries'};for($n=0;$n -lt $active.instructions.Count;$n++){if($n+1 -lt $active.instructions.Count){$active.instructions[$n]['end_cycle']=$active.instructions[$n+1].cycle}else{$active.instructions[$n]['end_cycle']=$fields.cycle};if($active.instructions[$n].end_cycle -le $active.instructions[$n].cycle){throw 'Non-positive instruction interval'}};$active['before_hex']=Hex $before;$active['after_hex']=Hex $after;$active.instructions=@($active.instructions.ToArray());$rows.Add($active);$active=$null}}
if($null -ne $active -or $rows.Count -ne 2 -or $states.Count -ne 2){throw 'Truncated scheduler call capture'}
$expected=[ordered]@{pc=0xFEC9;s=0x700;u=0x600;x=0x8784;y=0x1A0;dp=0;cc=0x50}
foreach($row in $rows){foreach($key in $expected.Keys){if($row.initial[$key] -ne $expected[$key]){throw "Initial $key differs"}}}
$regions=@(
 [ordered]@{name='FEC9 JSR5CD0 and FECC CLR2C';address=0xFEC9;bytes_hex=(Hex $rom[0xFEC9..(0xFEC9+7)]);sha256=(HashBytes $rom[0xFEC9..(0xFEC9+7)])},
 [ordered]@{name='5D38 decrement and 5D3A RTS';address=0x5D38;bytes_hex=(Hex $rom[0x5D38..(0x5D38+5)]);sha256=(HashBytes $rom[0x5D38..(0x5D38+5)])},
 [ordered]@{name='5963 dispatch table through5C17';address=0x5963;bytes_hex=(Hex $rom[0x5963..(0x5963+692)]);sha256=(HashBytes $rom[0x5963..(0x5963+692)])},
 [ordered]@{name='8739 sound stream through879E';address=0x8739;bytes_hex=(Hex $rom[0x8739..(0x8739+101)]);sha256=(HashBytes $rom[0x8739..(0x8739+101)])})
$natural=$null;if($NaturalRunsDirectory){$natural=[ordered]@{};foreach($name in @('scheduler-a','scheduler-b')){$run="$NaturalRunsDirectory/$name";$trace="$run/routine.trace";$lines=@(Get-Content $trace);if($lines.Count -lt 2){throw "Natural trace $name differs"};$rx='^A=([0-9A-F]{2}) B=([0-9A-F]{2}) DP=([0-9A-F]{2}) X=([0-9A-F]{4}) S=([0-9A-F]{4}) CC=([0-9A-F]{2}) LOCK=([0-9A-F]{2}) TICKS=([0-9A-F]{4}) HEAD=([0-9A-F]{4}) ([0-9A-F]{4}): (.*)$';if($lines[0] -notmatch $rx){throw "Natural trace $name format differs"};$first=[ordered]@{x=$Matches[4];s=$Matches[5];ticks=$Matches[8];head=$Matches[9];pc=$Matches[10];line=[string]$lines[0]};if($lines[-1] -notmatch $rx){throw "Natural return $name differs"};$last=[ordered]@{x=$Matches[4];s=$Matches[5];ticks=$Matches[8];head=$Matches[9];pc=$Matches[10];line=[string]$lines[-1]};if($first.pc -notin @('5CD0','5CD2') -or $last.pc -ne 'FECC' -or $first.ticks -ne '0000' -or $last.ticks -ne '0001' -or $first.head -ne '0000' -or $last.head -ne '0000' -or $first.x -ne $last.x -or ([Convert]::ToInt32($last.s,16) - [Convert]::ToInt32($first.s,16) -ne 2)){throw "Natural scheduler return $name differs"};if((Get-Content "$run/exit-code.txt" -Raw).Trim() -ne '0' -or (Get-Content "$run/initial-state.txt" -Raw) -notmatch 'NVRAM: absent'){throw "Natural run $name provenance differs"};$runArguments=@((Get-Content "$run/arguments.json" -Raw|ConvertFrom-Json)|ForEach-Object {$_});if($runArguments -notcontains '-noreadconfig' -or $runArguments -notcontains 'E:\Arcade\MAME0266\roms'){throw "Natural run $name arguments differ"};$natural[$name]=[ordered]@{trace_sha256=(Hash $trace);entry_s=[Convert]::ToUInt16($first.s,16);return_s=[Convert]::ToUInt16($last.s,16);entry_pc=[Convert]::ToUInt16($first.pc,16);return_pc=[Convert]::ToUInt16($last.pc,16);ticks=[Convert]::ToUInt32($last.ticks,16);entry_line=[string]$first.line;return_line=[string]$last.line;initial_state_sha256=(Hash "$run/initial-state.txt");debugger_sha256=(Hash "$run/debugger.cmd");arguments_sha256=(Hash "$run/arguments.json");hashes_sha256=(Hash "$run/hashes.json")}}}
[ordered]@{classification='Synthetic original FEC9 JSR5CD0 return FECC/CLR2C; full2KB RAM, masked IRQ, recorded initial registers/S, empty and queued8784 cases. Natural scheduler-a/b empty return comparison only.';return_contract=[ordered]@{entry=0xFEC9;instruction='BD5CD0';return_address=$returnAddress;return_instruction='0F2C'};rom_regions=$regions;natural=$natural;rows=@($rows.ToArray())}|ConvertTo-Json -Depth 8|Set-Content "$target/timer1-scheduler-call.json"
$regionSeeds=@($cases|ForEach-Object {[ordered]@{id=$_.id;sha256=(Hash "$RunDirectory/$($_.seed)")}})
[ordered]@{source_run=$RunDirectory;debug_sha256=(Hash "$RunDirectory/debug.log");cases_sha256=(Hash "$RunDirectory/cases.json");debugger_sha256=(Hash "$RunDirectory/debugger.cmd");arguments_sha256=(Hash "$RunDirectory/arguments.json");rom_sha1=(Hash $RomPath 'SHA1');provenance=(Get-Content "$RunDirectory/provenance.json" -Raw|ConvertFrom-Json);contract_rom_sha256=(HashBytes $rom[0xFEC9..(0xFEC9+7)]);cases=$rows.Count;initial_states=@($rows|ForEach-Object {[ordered]@{id=$_.case.id;pc=$_.initial.pc;cycle=$_.initial.cycle;s=$_.initial.s;u=$_.initial.u;x=$_.initial.x;y=$_.initial.y;dp=$_.initial.dp;cc=$_.initial.cc}});seeds=$regionSeeds;rom_regions=@($regions|ForEach-Object {[ordered]@{address=$_.address;sha256=$_.sha256}});natural=$natural}|ConvertTo-Json -Depth 8|Set-Content "$target/timer1-scheduler-call-verification.json";Write-Output 'Curated2 FEC9 scheduler call cases'
